package com.exampro.controller;import com.exampro.dto.ApiDtos.*;import com.exampro.service.SubjectService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class SubjectController {private final SubjectService s;public SubjectController(SubjectService s){this.s=s;}@GetMapping("/subjects") public List<SubjectResponse> all(){return s.all();}@GetMapping("/subjects/{id}") public SubjectResponse get(@PathVariable Long id){return s.get(id);}@PostMapping("/admin/subjects") public ResponseEntity<SubjectResponse> create(@Valid @RequestBody SubjectRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(r));}@PutMapping("/admin/subjects/{id}") public SubjectResponse update(@PathVariable Long id,@Valid @RequestBody SubjectRequest r){return s.update(id,r);}@DeleteMapping("/admin/subjects/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}}
